import json; from maya_intent_cues import classify_opening; cases=[("What is philosophy?","definition_or_information"),("Who is Carl Jung?","person_or_entity"),("Where is Ubuntu?","location"),("When was Nietzsche born?","time_or_history"),("Why does Maya sleep?","reason_or_cause"),("How does Maya learn?","process_or_explanation"),("Which model is better?","choice_or_comparison"),("Can Maya hear me?","maya_capability_or_action"),("Could you help me?","polite_request_or_capability"),("Tell me about trading.","request_for_explanation"),("Explain philosophy.","request_for_explanation"),("Can you tell me why philosophy matters?","reason_or_cause"),("What is philosophy, and why does it matter?","reason_or_cause"),("How does Maya learn, but what does approval change?","definition_or_information"),("Although I asked what Maya can do, compare local and cloud.","choice_or_comparison"),("Tell me whether you can wake Maya, and then explain how.","request_for_explanation"),("Why do you not research automatically?","reason_or_cause"),("Can Maya self-evolve, not rewrite permissions?","definition_or_information"),("What should I do instead, and why?","reason_or_cause"),("Is it a fact, or should I ask why?","reason_or_cause"),("Who is this about, and where are they?","location"),("Where is the file, but when was it changed?","time_or_history"),("When did it happen, and how did it work?","process_or_explanation"),("How can I compare these options?","process_or_explanation"),("Which is better, however, why?","reason_or_cause"),("What do you know, rather than what do you guess?","definition_or_information"),("Can you explain, but not execute?","request_for_explanation"),("Could you tell me how, instead of whether?","process_or_explanation"),("Do you know why this happens?","reason_or_cause"),("Does Maya learn, or only store patterns?","definition_or_information"),("Are you awake, and if not, why?","reason_or_cause"),("Is Maya active, but what does active mean?","definition_or_information"),("Hello Maya, can you hear me?","statement_or_general_request"),("Although tired, I want an explanation.","statement_or_general_request"),("However, tell me about memory.","request_for_explanation"),("Rather than answer, compare choices.","choice_or_comparison"),("Instead, explain the safer option.","request_for_explanation"),("Not whether you can, but why you should.","reason_or_cause"),("What if the first cue is wrong?","definition_or_information"),("Can you tell me what the cue means?","definition_or_information"),("Why, if you can, would you choose that?","reason_or_cause"),("How, despite timeout, can Maya respond?","process_or_explanation"),("Tell me what to compare, not which to choose.","definition_or_information"),("Which one should I approve?","choice_or_comparison"),("Where, however, is the source?","location"),("When, rather than why, did it start?","time_or_history"),("Who, if not Maya, should review this?","person_or_entity"),("Do not act; explain the command.","request_for_explanation"),("Is this safe, or should I correct it?","fact_check_or_definition"),("Can you answer, even though Ollama is slow?","maya_capability_or_action"),("The system is awake, but I need an explanation.","statement_or_general_request")]; cases=cases[:50]; rows=[]; raw=sum(classify_opening(s)["raw_intent"]==e for s,e in cases); adj=sum(classify_opening(s)["intent"]==e for s,e in cases); [rows.append({"sentence":s,"expected":e,"raw":classify_opening(s)["raw_intent"],"adjusted":classify_opening(s)["intent"],"markers":classify_opening(s)["contrastive_markers"]}) for s,e in cases if classify_opening(s)["intent"]!=e]; print(json.dumps({"cases":len(cases),"raw_correct":raw,"adjusted_correct":adj,"raw_accuracy":raw/len(cases),"adjusted_accuracy":adj/len(cases),"adjusted_misclassifications":rows},indent=2))


